// Package testcert provides a static X509 client certificate for use in tests.
//
// Tests which need a trusted TLS client certificate should use the certificate
// provided here instead of embedding their own copy, so the expected
// fingerprint only has to be maintained in a single place.
package testcert

// ClientCertificate is a X509 PEM encoded client certificate with the same
// properties as a certificate generated by GenerateMemCert(true, false) from
// github.com/lxc/incus/v7/shared/tls, but with a generic subject, which does not
// reference any real host or user.
//
// It can be regenerated with openssl as follows:
//
//	cat > openssl.cnf <<'EOF'
//	[req]
//	distinguished_name = dn
//	prompt             = no
//	x509_extensions    = client_cert
//
//	[dn]
//	O  = Linux Containers
//	CN = user@host.some.tld
//
//	[client_cert]
//	keyUsage               = critical, digitalSignature, keyEncipherment
//	extendedKeyUsage       = clientAuth
//	basicConstraints       = critical, CA:FALSE
//	subjectKeyIdentifier   = none
//	authorityKeyIdentifier = none
//	EOF
//
//	openssl ecparam -name secp384r1 -genkey -noout -out client.key
//	openssl req -new -x509 -sha384 -key client.key -out client.crt -days 3650 -config openssl.cnf
//
// Regenerating the certificate does change its fingerprint, therefore
// ClientCertificateFingerprint has to be updated as well.
const ClientCertificate = `-----BEGIN CERTIFICATE-----
MIIB4zCCAWqgAwIBAgIUZT1U82k44TuXkKcq1jdXYxaZDDgwCgYIKoZIzj0EAwMw
ODEZMBcGA1UECgwQTGludXggQ29udGFpbmVyczEbMBkGA1UEAwwSdXNlckBob3N0
LnNvbWUudGxkMB4XDTI2MDgxMTA2MTgyOFoXDTM2MDgwODA2MTgyOFowODEZMBcG
A1UECgwQTGludXggQ29udGFpbmVyczEbMBkGA1UEAwwSdXNlckBob3N0LnNvbWUu
dGxkMHYwEAYHKoZIzj0CAQYFK4EEACIDYgAEW9cy2pfFn/i3XdgNGl5WqLkthPHS
4x5zQubllNA66BAcV23vVqJ0xXMfKctlVgrU0NRSNEn5mX7gDnfHGzS33pfQbxMO
ThiwdAX4SpN6rs2dZGpI/qNwA0sS2NhXGNm7ozUwMzAOBgNVHQ8BAf8EBAMCBaAw
EwYDVR0lBAwwCgYIKwYBBQUHAwIwDAYDVR0TAQH/BAIwADAKBggqhkjOPQQDAwNn
ADBkAjB4QSY3y5U08XfwWR3eFZU2fH4IDVf3GHEBIaEtNlXzBqBCyrOcUz343hI4
Nq1cnl8CMBhlQlZZuq8pgMkj3kCwBREpfCFxfOu0b1PMOW/4mX9NSvh44L4u3Qpn
QnQF/nCEsw==
-----END CERTIFICATE-----`

// ClientCertificateFingerprint is the canonical SHA256 fingerprint of
// ClientCertificate, in the lower case, colon free form used by
// CertFingerprint from github.com/lxc/incus/v7/shared/tls.
//
// It can be calculated with openssl as follows:
//
//	openssl x509 -in client.crt -noout -fingerprint -sha256 | sed 's/.*=//; s/://g' | tr '[:upper:]' '[:lower:]'
const ClientCertificateFingerprint = "b4e08ef4c7fb1c14b4b73422e9375fa3bdd992836ed58bc78673dcd532083ad0"

